#define NULL 0char *getenv();char *ctermid(sp)char *sp;{    static char termid[32];    char *cp;    if(termid[0] == '\0') {	cp = getenv("PORT");	if(cp == NULL || *cp == '\0') return NULL;	if(*cp=='/') strcpy(termid, cp);	else {    	    termid[0] = '/';	    strcpy(&termid[1], cp);	}    }    if(sp != NULL) {        strcpy(sp, termid);	return sp;    }    return termid;}